<template>
  <div class="container toml-container">
    <div class="row q-pt-sm q-pb-sm justify-between items-center">
      <div>
        <FilterBadges
          v-if="tableRef?.columnFilter?.hasActiveFilters?.value"
          :filters="tableRef?.columnFilter?.activeFilters?.value || []"
          :columns="columns"
          @remove="(col) => tableRef?.columnFilter?.clearFilter(col)"
        />
      </div>
      <f-btn
        icon="add"
        :label="$t('new')"
        @click="createNew"
      />
    </div>
    <div class="full-width toml-table-wrapper">
      <DocBitsTable
      ref="tableRef"
      :rows="tomlSamples"
      :columns="columns"
      :loading="isLoading"
      row-key="id"
      table-id="toml_list_table"
      :features="{
        sorting: true,
        clientSideSort: true,
        filtering: true,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: true,
        clientSidePagination: true,
        columnReorder: false,
        columnSettings: false,
        stickyFirstColumn: false,
        stickyLastColumn: true,
      }"
      :pagination="{ page: 1, rowsPerPage: 25 }"
      :row-actions="rowActions"
      no-data-label="no_record_found"
      table-class="toml-table-height"
      flat-style
      @row-action="handleRowAction"
      @row-click="handleRowClick"
    >
      <!-- Name column with badge for default items -->
      <template #body-cell-mapping_name="{ row }">
        <span class="text-primary cursor-pointer q-pr-sm">
          {{ row.mapping_name }}
        </span>
        <q-badge
          transparent
          align="middle"
          v-if="isDefaultItem(row)"
          color="orange"
        >
          {{ $t('default') }}
        </q-badge>
      </template>

      <!-- Description column with tooltip -->
      <template #body-cell-mapping_description="{ row }">
        <div class="ellipsis-container">
          <div class="ellipsis-text">
            {{ row.mapping_description || '-' }}
            <q-tooltip v-if="row.mapping_description">
              {{ row.mapping_description }}
            </q-tooltip>
          </div>
        </div>
      </template>

      <!-- Last modified by column -->
      <template #body-cell-last_modified_by="{ row }">
        {{ getUserName(row.last_modified_by) }}
      </template>

      <!-- Last modified on column -->
      <template #body-cell-last_modified_on="{ row }">
        {{ row.last_modified_on ? formatDateAccordingToPreference(row.last_modified_on) : '-' }}
      </template>
      </DocBitsTable>
    </div>
  </div>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import cache from 'src/utils/cache';
import { defineComponent, ref, computed } from 'vue';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import { exportApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import dateUtils from 'src/utils/date';
import { ApiExceptions } from 'src/exceptions/index';
import { M3_TOML_MAPPING, RULE_MANAGER, DEFAULT_ORG_UUID } from 'src/constants';
import { DocBitsTable, FilterBadges } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';

export default defineComponent({
  props: {
    list_name: {
      type: String,
      default: '',
    },
  },
  mixins: [helperMixin, cache, dateUtils],
  components: { Loader, DocBitsTable, FilterBadges },
  data() {
    return {};
  },
  mounted: function () {
    this.init();
  },
  methods: {
    async init() {
      await this.prepareUsersDropdown();
      this.loadTomlSamples();
    },
    getUserName(userId: string): string {
      if (!userId) return '-';
      // API returns string ID, usersMap uses number keys
      const user = this.usersMap.get(Number(userId));
      if (user) {
        return `${user.first_name} ${user.last_name}`;
      }
      return userId;
    },
    async loadTomlSamples() {
      try {
        this.isLoading = true;
        this.showLoading();
        const response =
          await exportApiService.getExportConfigurationMappingSamples(
            M3_TOML_MAPPING,
          );

        if (response && !response.success && response.exception.detail) {
          throw { message: response.exception.detail };
        }

        this.tomlSamples = response.data;
      } catch (err: any) {
        logError(err);
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.isLoading = false;
        this.hideLoading();
      }
    },
    isDefaultItem(row: any): boolean {
      return row.org_id === DEFAULT_ORG_UUID;
    },
    editTomlFile(row: any, createDuplicate: boolean) {
      let isDefault = row.org_id === DEFAULT_ORG_UUID;
      if (createDuplicate) {
        isDefault = false;
      }

      const dataToCache = {
        mapping_description: row.mapping_description,
        mapping_name: createDuplicate
          ? row.mapping_name + ' (Copy)'
          : row.mapping_name,
        mapping_value: row.mapping_value,
        id: createDuplicate ? '' : row.id,
        isDefault: isDefault,
      };

      this.setDataToSessionStorage(RULE_MANAGER, dataToCache);
      this.$router.push('/settings/rule-management');
    },
    async deleteRow(row: any) {
      if (row.org_id === DEFAULT_ORG_UUID) {
        return;
      }

      try {
        this.showLoading();
        const response =
          await exportApiService.deleteExportConfigurationMappingSample(row.id);

        if (!response || !response.success) {
          throw response;
        }

        notify.success(this.$t('configuration_deleted'));
        await this.loadTomlSamples();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    handleRowAction(payload: RowActionPayload) {
      const row = payload.row;
      if (payload.action === 'edit') {
        this.editTomlFile(row, false);
      } else if (payload.action === 'duplicate') {
        this.editTomlFile(row, true);
      } else if (payload.action === 'delete') {
        this.deleteRow(row);
      }
    },
    handleRowClick(payload: { row: any }) {
      this.editTomlFile(payload.row, false);
    },
    createNew() {
      // Use the default record as template (if available)
      const template = this.tomlSamples.find(
        (item: any) => item.org_id === DEFAULT_ORG_UUID
      );

      const dataToCache = {
        mapping_description: '',
        mapping_name: '',
        mapping_value: template?.mapping_value || '',
        id: '',
        isDefault: false,
      };

      this.setDataToSessionStorage(RULE_MANAGER, dataToCache);
      this.$router.push('/settings/rule-management');
    },
  },

  setup() {
    const { t } = useTranslate();
    // Dropdown store for user lookup
    const dropdownStore = useDropdownStore();
    const { usersMap } = storeToRefs(dropdownStore);
    const { prepareUsersDropdown } = dropdownStore;

    // Column definitions for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'mapping_name',
        label: t.value('name'),
        field: 'mapping_name',
        sortable: true,
        align: 'left',
        style: 'width: 25%',
      },
      {
        name: 'mapping_description',
        label: t.value('description'),
        field: 'mapping_description',
        sortable: true,
        align: 'left',
      },
      {
        name: 'last_modified_by',
        label: t.value('last_modified_by'),
        field: 'last_modified_by',
        sortable: true,
        align: 'left',
        style: 'width: 150px',
        filter: false,
      },
      {
        name: 'last_modified_on',
        label: t.value('last_modified_at'),
        field: 'last_modified_on',
        sortable: true,
        align: 'left',
        style: 'width: 150px',
        filter: false,
      },
    ]);

    // Row actions for edit, duplicate, and delete
    // Delete action is hidden for default items (org_id === DEFAULT_ORG_UUID)
    const rowActions: RowActionItem[] = [
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
        color: 'primary',
      },
      {
        key: 'duplicate',
        label: 'duplicate',
        icon: 'content_copy',
        color: 'grey-7',
      },
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
        show: (row: any) => row.org_id !== DEFAULT_ORG_UUID,
      },
    ];

    // Template ref to access table's filter state
    const tableRef = ref<InstanceType<typeof DocBitsTable> | null>(null);

    return {
      tomlSamples: ref([] as any),
      columns,
      rowActions,
      isLoading: ref(false),
      tableRef,
      usersMap,
      prepareUsersDropdown,
      t,
    };
  },
});
</script>
<style scoped lang="scss">
.toml-container {
  padding-top: 0;
}

.filter-badges-toolbar {
  min-height: 40px;
  display: flex;
  align-items: center;
}

.ellipsis-container {
  display: grid;
  grid-template-columns: 100% auto;
  overflow: hidden;
}

.ellipsis-text {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

:deep(.toml-table-height) {
  height: calc(100vh - 190px) !important;
}
</style>
